module.exports = function (api) {
  api.cache(true);
  return {
    presets: ["babel-preset-expo"],
    plugins: [
      [
        "module-resolver",
        {
          root: ["./"],
          alias: {
            "@wishin/domain": path.resolve(
              __dirname,
              "../../packages/domain/src",
            ),
            "@wishin/infrastructure": path.resolve(
